function navigate(target){document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.dataset.page===target));document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.target===target));document.getElementById('pageTitle').textContent=titles[target];window.scrollTo({top:0,behavior:'smooth'});}
