const burnInput=document.getElementById('todayBurnInput'),durationInput=document.getElementById('todayDurationInput');
function localDateKey(date=new Date()){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`;}
burnInput.value=homeStats.burn??280;durationInput.value=homeStats.duration??45;let trainingDays=homeStats.trainingDays??6;
homeStats.daily=homeStats.daily||{};const todayKey=localDateKey();
if(!Object.keys(homeStats.daily).length){const samples=[[0,280,45],[1,0,0],[2,320,50],[3,260,40],[4,0,0],[5,410,65],[6,300,55]];samples.forEach(([offset,burn,duration])=>{const date=new Date();date.setDate(date.getDate()-offset);homeStats.daily[localDateKey(date)]={burn,duration};});}
if(!Array.isArray(homeStats.checkins)){homeStats.checkins=[];const offsets=[1,2,4,6,8,10,12,15,18,21];for(let i=0;i<Math.min(trainingDays,offsets.length);i++){const date=new Date();date.setDate(date.getDate()-offsets[i]);homeStats.checkins.push(localDateKey(date));}if(homeStats.lastCheckin&&!homeStats.checkins.includes(homeStats.lastCheckin))homeStats.checkins.push(homeStats.lastCheckin);}
function saveHomeStats(){homeStats.burn=+burnInput.value||0;homeStats.duration=+durationInput.value||0;homeStats.trainingDays=trainingDays;homeStats.daily[todayKey]={burn:homeStats.burn,duration:homeStats.duration};try{localStorage.setItem('fitnessHomeStats',JSON.stringify(homeStats));}catch{}}
let calendarView=new Date(new Date().getFullYear(),new Date().getMonth(),1);
function renderCalendar(){const y=calendarView.getFullYear(),m=calendarView.getMonth(),today=new Date(),days=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7;document.getElementById('calendarTitle').textContent=`${y}年${m+1}月`;let html='<span class="calendar-blank"></span>'.repeat(offset);for(let day=1;day<=days;day++){const date=new Date(y,m,day),key=localDateKey(date),checked=homeStats.checkins.includes(key),future=date>new Date(today.getFullYear(),today.getMonth(),today.getDate()),isToday=key===todayKey;html+=`<span class="calendar-day ${checked?'checked':future?'future':'missed'} ${isToday?'today':''}"><b>${day}</b><i>${checked?'✓':future?'':'·'}</i></span>`;}document.getElementById('checkinCalendar').innerHTML=html;}
function renderCheckin(){const checked=homeStats.checkins.includes(todayKey);document.getElementById('trainingDays').textContent=trainingDays;document.getElementById('checkinTotal').textContent=trainingDays;document.getElementById('checkinDate').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});document.getElementById('checkinStatus').textContent=checked?'今日训练已签到':'今天还未签到';document.getElementById('checkinButton').textContent=checked?'今日已签到 ✓':'今日签到';document.getElementById('checkinButton').disabled=checked;renderCalendar();}
function weekDateKeys(){const now=new Date(),monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const date=new Date(monday);date.setDate(monday.getDate()+i);return localDateKey(date);});}
function openStatHistory(type){saveHomeStats();const isBurn=type==='burn',unit=isBurn?'千卡':'分钟',keys=weekDateKeys(),values=keys.map(key=>homeStats.daily[key]?.[type]||0),monthPrefix=todayKey.slice(0,7),weekTotal=values.reduce((a,b)=>a+b,0),monthTotal=Object.entries(homeStats.daily).filter(([key])=>key.startsWith(monthPrefix)).reduce((sum,[,value])=>sum+(value[type]||0),0),max=Math.max(...values,1);document.getElementById('statHistoryTitle').textContent=isBurn?'消耗记录':'训练时长记录';document.getElementById('weekStatTotal').textContent=weekTotal.toLocaleString();document.getElementById('monthStatTotal').textContent=monthTotal.toLocaleString();document.getElementById('weekStatUnit').textContent=unit;document.getElementById('monthStatUnit').textContent=unit;document.getElementById('statHistoryBars').innerHTML=values.map((value,i)=>`<div><em>${value||'-'}</em><i><b style="height:${value?Math.max(8,value/max*72):3}px"></b></i><span>${'一二三四五六日'[i]}</span></div>`).join('');document.getElementById('statHistoryList').innerHTML=keys.map((key,i)=>`<div><span>周${'一二三四五六日'[i]} · ${key.slice(5).replace('-','/')}</span><b>${values[i]} ${unit}</b></div>`).join('');document.getElementById('statHistoryModal').showModal();}
[burnInput,durationInput].forEach(input=>{input.addEventListener('input',saveHomeStats);input.addEventListener('change',()=>toast('今日训练数据已保存'));});
document.getElementById('openBurnHistory').onclick=()=>openStatHistory('burn');document.getElementById('openDurationHistory').onclick=()=>openStatHistory('duration');document.getElementById('closeStatHistory').onclick=()=>document.getElementById('statHistoryModal').close();
document.getElementById('openCheckin').onclick=()=>{calendarView=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderCheckin();document.getElementById('checkinModal').showModal();};document.getElementById('closeCheckin').onclick=()=>document.getElementById('checkinModal').close();document.getElementById('calendarPrev').onclick=()=>{calendarView.setMonth(calendarView.getMonth()-1);renderCalendar();};document.getElementById('calendarNext').onclick=()=>{calendarView.setMonth(calendarView.getMonth()+1);renderCalendar();};document.getElementById('checkinButton').onclick=()=>{if(homeStats.checkins.includes(todayKey))return;homeStats.checkins.push(todayKey);homeStats.lastCheckin=todayKey;trainingDays+=1;saveHomeStats();renderCheckin();toast('签到成功，训练天数 +1');};saveHomeStats();renderCheckin();

document.getElementById('foodCalculate').onclick=()=>{const per100=+document.getElementById('foodCalories').value||0;const weight=+document.getElementById('foodWeight').value||0;const result=Math.round(per100*weight/100);document.getElementById('foodResult').textContent=result+' 千卡';document.getElementById('riceBowls').textContent=(result/230).toFixed(1)+' 碗米饭';toast('热量计算完成');};

